  async function testOperationalKnowledgeProductiveInfluenceContract() {
    setLoading(true);

    try {
      const detectedPatterns = await detectMemoryPatterns();

      const recommendationsBeforeInfluence =
        generateRecommendationsFromPatterns(detectedPatterns);

      const decisionsBeforeInfluence =
        generateOperationalDecisions(
          detectedPatterns,
          recommendationsBeforeInfluence
        );

      /*
      * FASE 24.8 — Influencia productiva explícita
      * del conocimiento utilizado por el consumidor.
      *
      * FASE 24.7 estableció:
      *
      * ProductiveKnowledgeConsumption
      *        ↓
      * useProductiveKnowledge()
      *        ↓
      * ProductiveKnowledgeUtilization
      *
      * FASE 24.8 introduce:
      *
      * ProductiveKnowledgeUtilization
      *        ↓
      * influenceProductiveKnowledge()
      *        ↓
      * ProductiveKnowledgeInfluence
      *
      * La influencia NO constituye todavía:
      *
      * - efecto observable;
      * - cambio de recomendación;
      * - cambio de decisión;
      * - ponderación;
      * - ranking;
      * - selección;
      * - ejecución.
      */
      const recommendationsSnapshot = JSON.stringify(
        recommendationsBeforeInfluence
      );

      const decisionsSnapshot = JSON.stringify(
        decisionsBeforeInfluence
      );

      const controlledPatterns: MemoryPattern[] = [
        {
          id: 'pattern-controlled-productive-influence-24-8',
          title:
            'Patrón controlado de influencia productiva',
          description:
            'Patrón controlado utilizado exclusivamente por FASE 24.8.',
          score: 100,
          occurrences: 4,
          kind: 'recommendation-deviation-recurrence',
          context: {
            movementType: 'reubicacion',
            deviationReason:
              'motivo-controlado-productive-influence-24-8',
          },
          evidence: {
            memoryIds: [
              'memory-controlled-productive-influence-24-8-1',
              'memory-controlled-productive-influence-24-8-2',
              'memory-controlled-productive-influence-24-8-3',
              'memory-controlled-productive-influence-24-8-4',
            ],
          },
        },
      ];

      const controlledKnowledge =
        generateOperationalKnowledge(controlledPatterns);

      if (controlledKnowledge.length !== 1) {
        throw new Error(
          `FASE 24.8 esperaba exactamente 1 conocimiento controlado y generó ${controlledKnowledge.length}.`
        );
      }

      const knowledge = controlledKnowledge[0];

      if (!knowledge) {
        throw new Error(
          'FASE 24.8 no pudo resolver el conocimiento controlado.'
        );
      }

      const productiveContext = {
        movementType: 'reubicacion' as const,
      };

      const eligibility =
        evaluateOperationalKnowledgeEligibility(
          knowledge,
          productiveContext
        );

      if (
        eligibility.eligible !== true ||
        eligibility.reason !== 'context-compatible'
      ) {
        throw new Error(
          'FASE 24.8 no pudo establecer elegibilidad contextual previa.'
        );
      }

      const consideration =
        considerOperationalKnowledge(eligibility);

      if (!consideration) {
        throw new Error(
          'FASE 24.8 no pudo establecer consideración previa del conocimiento.'
        );
      }

      const productiveInput =
        presentOperationalKnowledge(
          knowledge,
          consideration,
          productiveContext
        );

      if (!productiveInput) {
        throw new Error(
          'FASE 24.8 no pudo obtener ProductiveKnowledgeInput previo a la influencia.'
        );
      }

      const reception =
        receiveProductiveKnowledge(productiveInput);

      const availability =
        makeProductiveKnowledgeAvailable(reception);

      const consumerA: ProductiveKnowledgeConsumerRef = {
        id: 'productive-consumer-a-24-8',
      };

      const consumerB: ProductiveKnowledgeConsumerRef = {
        id: 'productive-consumer-b-24-8',
      };

      const exposureA =
        exposeProductiveKnowledge(
          availability,
          consumerA
        );

      const exposureB =
        exposeProductiveKnowledge(
          availability,
          consumerB
        );

      const accessA =
        accessProductiveKnowledge(exposureA);

      const accessB =
        accessProductiveKnowledge(exposureB);

      const consumptionA =
        consumeProductiveKnowledge(accessA);

      const consumptionB =
        consumeProductiveKnowledge(accessB);

      const utilizationA =
        useProductiveKnowledge(consumptionA);

      const utilizationB =
        useProductiveKnowledge(consumptionB);

      /*
      * utilized != influential
      *
      * ProductiveKnowledgeUtilization no crea
      * automáticamente ProductiveKnowledgeInfluence.
      *
      * La influencia requiere un acto explícito:
      * influenceProductiveKnowledge().
      */
      const utilizationASnapshot =
        JSON.stringify(utilizationA);

      const utilizationBSnapshot =
        JSON.stringify(utilizationB);

      /*
      * Influencia explícita únicamente sobre A.
      */
      const influenceA =
        influenceProductiveKnowledge(utilizationA);

      if (influenceA.utilization !== utilizationA) {
        throw new Error(
          'FASE 24.8 no conservó la misma ProductiveKnowledgeUtilization durante la influencia.'
        );
      }

      /*
      * Conservación transitiva exacta.
      */
      if (
        influenceA.utilization.consumption !==
        consumptionA
      ) {
        throw new Error(
          'FASE 24.8 perdió ProductiveKnowledgeConsumption durante la influencia.'
        );
      }

      if (
        influenceA.utilization.consumption.access !==
        accessA
      ) {
        throw new Error(
          'FASE 24.8 perdió ProductiveKnowledgeAccess durante la influencia.'
        );
      }

      if (
        influenceA.utilization.consumption.access.exposure !==
        exposureA
      ) {
        throw new Error(
          'FASE 24.8 perdió ProductiveKnowledgeExposure durante la influencia.'
        );
      }

      if (
        influenceA.utilization.consumption.access.exposure
          .consumer !== consumerA
      ) {
        throw new Error(
          'FASE 24.8 perdió la referencia del consumidor durante la influencia.'
        );
      }

      if (
        influenceA.utilization.consumption.access.exposure
          .availability !== availability
      ) {
        throw new Error(
          'FASE 24.8 perdió ProductiveKnowledgeAvailability durante la influencia.'
        );
      }

      if (
        influenceA.utilization.consumption.access.exposure
          .availability.reception !== reception
      ) {
        throw new Error(
          'FASE 24.8 perdió ProductiveKnowledgeReception durante la influencia.'
        );
      }

      if (
        influenceA.utilization.consumption.access.exposure
          .availability.reception.input !== productiveInput
      ) {
        throw new Error(
          'FASE 24.8 perdió ProductiveKnowledgeInput durante la influencia.'
        );
      }

      /*
      * Influence A no puede mutar Utilization A
      * ni afectar Utilization B.
      */
      if (
        JSON.stringify(utilizationA) !==
        utilizationASnapshot
      ) {
        throw new Error(
          'FASE 24.8 modificó ProductiveKnowledgeUtilization durante la influencia.'
        );
      }

      if (
        JSON.stringify(utilizationB) !==
        utilizationBSnapshot
      ) {
        throw new Error(
          'FASE 24.8 propagó o modificó indebidamente una utilización independiente.'
        );
      }

      /*
      * Control A/B:
      *
      * influir sobre Utilization A no produce
      * influencia automática sobre Utilization B.
      */
      const influenceB =
        influenceProductiveKnowledge(utilizationB);

      if (influenceB.utilization !== utilizationB) {
        throw new Error(
          'FASE 24.8 no conservó la segunda utilización durante su influencia independiente.'
        );
      }

      if (influenceA === influenceB) {
        throw new Error(
          'FASE 24.8 colapsó dos actos explícitos de influencia independientes.'
        );
      }

      if (
        influenceA.utilization === influenceB.utilization
      ) {
        throw new Error(
          'FASE 24.8 perdió la distinción entre utilizaciones productivas independientes.'
        );
      }

      /*
      * ProductiveKnowledgeInfluence debe ser un
      * contenedor mínimo.
      *
      * No puede adquirir semántica de efecto
      * observable ni de modificación productiva.
      */
      const forbiddenInfluenceProperties = [
        'consumption',
        'access',
        'exposure',
        'availability',
        'consumer',
        'consumerId',
        'consumerType',
        'input',
        'reception',
        'knowledgeId',
        'sourcePatternId',
        'knowledgeType',
        'context',
        'evidence',
        'score',
        'occurrences',
        'memoryIds',
        'strength',
        'weight',
        'support',
        'supportCount',
        'confidence',
        'priority',
        'purpose',
        'influential',
        'effect',
        'effectSize',
        'impact',
        'changed',
        'rank',
        'ranking',
        'selected',
        'selection',
        'decisionId',
        'recommendationId',
        'executed',
        'execution',
      ];

      const influenceRecord =
        influenceA as unknown as Record<
          string,
          unknown
        >;

      const detectedForbiddenInfluenceProperty =
        forbiddenInfluenceProperties.find(
          (property) => property in influenceRecord
        );

      if (detectedForbiddenInfluenceProperty) {
        throw new Error(
          `FASE 24.8 introdujo indebidamente la propiedad "${detectedForbiddenInfluenceProperty}" dentro de ProductiveKnowledgeInfluence.`
        );
      }

      /*
      * La influencia tampoco puede recuperar
      * evidencia ni atributos descartados antes.
      */
      const influencedInputRecord =
        influenceA.utilization.consumption.access.exposure.availability.reception.input as unknown as Record<
          string,
          unknown
        >;

      const forbiddenInputProperties = [
        'evidence',
        'score',
        'occurrences',
        'memoryIds',
        'strength',
        'weight',
        'support',
        'supportCount',
        'confidence',
        'priority',
        'consumerId',
        'consumerType',
        'purpose',
        'influential',
        'effect',
        'effectSize',
        'impact',
        'changed',
        'rank',
        'ranking',
        'selected',
        'selection',
        'decisionId',
        'recommendationId',
        'executed',
        'execution',
      ];

      const detectedForbiddenInputProperty =
        forbiddenInputProperties.find(
          (property) => property in influencedInputRecord
        );

      if (detectedForbiddenInputProperty) {
        throw new Error(
          `FASE 24.8 recuperó o introdujo indebidamente la propiedad "${detectedForbiddenInputProperty}" dentro del conocimiento influyente.`
        );
      }

      /*
      * Verificación productiva externa.
      *
      * Existe ProductiveKnowledgeInfluence,
      * pero todavía no existe efecto observable
      * sobre recomendaciones ni decisiones.
      */
      const recommendationsAfterInfluence =
        generateRecommendationsFromPatterns(
          detectedPatterns
        );

      const decisionsAfterInfluence =
        generateOperationalDecisions(
          detectedPatterns,
          recommendationsAfterInfluence
        );

      if (
        JSON.stringify(
          recommendationsAfterInfluence
        ) !== recommendationsSnapshot
      ) {
        throw new Error(
          'FASE 24.8 detectó modificación de recomendaciones productivas después de la influencia del conocimiento.'
        );
      }

      if (
        JSON.stringify(decisionsAfterInfluence) !==
        decisionsSnapshot
      ) {
        throw new Error(
          'FASE 24.8 detectó modificación, reordenamiento o ranking distinto de decisiones después de la influencia del conocimiento.'
        );
      }

      addLog(
        `FASE 24.8 OK: las utilizaciones del conocimiento ${productiveInput.knowledgeId} asociadas a ${consumerA.id} y ${consumerB.id} adquirieron influencia productiva mediante actos explícitos e independientes de ProductiveKnowledgeInfluence, conservando exactamente utilización, consumo, acceso, exposición, consumidor, disponibilidad, recepción y ProductiveKnowledgeInput.
        La utilización no produjo influencia automática; la influencia requirió influenceProductiveKnowledge() y no introdujo efecto observable, impacto, fuerza, ponderación, ranking, selección ni ejecución.
        Permanecieron intactas ${recommendationsAfterInfluence.length} recomendaciones y ${decisionsAfterInfluence.length} decisiones productivas.`
      );
    } catch (error) {
      console.error(error);

      addLog(
        error instanceof Error
          ? `Error en influencia productiva explícita del conocimiento operativo 24.8: ${error.message}`
          : 'Error inesperado en influencia productiva explícita del conocimiento operativo 24.8.'
      );
    } finally {
      setLoading(false);
    }
  }

  async function testOperationalKnowledgeProductiveRecommendationReachContract() {
    setLoading(true);

    try {
      const detectedPatterns = await detectMemoryPatterns();

      const recommendationsBeforeReach =
        generateRecommendationsFromPatterns(detectedPatterns);

      const decisionsBeforeReach =
        generateOperationalDecisions(
          detectedPatterns,
          recommendationsBeforeReach
        );

      /*
      * FASE 24.9 — Alcance productivo explícito
      * de la influencia del conocimiento operativo
      * sobre una recomendación productiva concreta.
      *
      * FASE 24.8 estableció:
      *
      * ProductiveKnowledgeUtilization
      *        ↓
      * influenceProductiveKnowledge()
      *        ↓
      * ProductiveKnowledgeInfluence
      *
      * FASE 24.9 introduce:
      *
      * ProductiveKnowledgeInfluence
      *        +
      * IntelligenceRecommendation
      *        ↓
      * reachProductiveRecommendation()
      *        ↓
      * ProductiveKnowledgeRecommendationReach
      *
      * El alcance NO constituye:
      *
      * - efecto observable sobre contenido;
      * - cambio de recomendación;
      * - cambio de prioridad;
      * - cambio de score;
      * - ranking;
      * - selección;
      * - ejecución;
      * - cambio de decisiones.
      */
      const recommendationsSnapshot = JSON.stringify(
        recommendationsBeforeReach
      );

      const decisionsSnapshot = JSON.stringify(
        decisionsBeforeReach
      );

      if (recommendationsBeforeReach.length < 1) {
        throw new Error(
          'FASE 24.9 esperaba al menos 1 recomendación productiva existente.'
        );
      }

      const recommendation = recommendationsBeforeReach[0];

      if (!recommendation) {
        throw new Error(
          'FASE 24.9 no pudo resolver una recomendación productiva concreta.'
        );
      }

      const recommendationSnapshot =
        JSON.stringify(recommendation);

      const controlledPatterns: MemoryPattern[] = [
        {
          id: 'pattern-controlled-productive-recommendation-reach-24-9',
          title:
            'Patrón controlado de alcance productivo sobre recomendación',
          description:
            'Patrón controlado utilizado exclusivamente por FASE 24.9.',
          score: 100,
          occurrences: 4,
          kind: 'recommendation-deviation-recurrence',
          context: {
            movementType: 'reubicacion',
            deviationReason:
              'motivo-controlado-productive-recommendation-reach-24-9',
          },
          evidence: {
            memoryIds: [
              'memory-controlled-productive-recommendation-reach-24-9-1',
              'memory-controlled-productive-recommendation-reach-24-9-2',
              'memory-controlled-productive-recommendation-reach-24-9-3',
              'memory-controlled-productive-recommendation-reach-24-9-4',
            ],
          },
        },
      ];

      const controlledKnowledge =
        generateOperationalKnowledge(controlledPatterns);

      if (controlledKnowledge.length !== 1) {
        throw new Error(
          `FASE 24.9 esperaba exactamente 1 conocimiento controlado y generó ${controlledKnowledge.length}.`
        );
      }

      const knowledge = controlledKnowledge[0];

      if (!knowledge) {
        throw new Error(
          'FASE 24.9 no pudo resolver el conocimiento controlado.'
        );
      }

      const productiveContext = {
        movementType: 'reubicacion' as const,
      };

      const eligibility =
        evaluateOperationalKnowledgeEligibility(
          knowledge,
          productiveContext
        );

      if (
        eligibility.eligible !== true ||
        eligibility.reason !== 'context-compatible'
      ) {
        throw new Error(
          'FASE 24.9 no pudo establecer elegibilidad contextual previa.'
        );
      }

      const consideration =
        considerOperationalKnowledge(eligibility);

      if (!consideration) {
        throw new Error(
          'FASE 24.9 no pudo establecer consideración previa del conocimiento.'
        );
      }

      const productiveInput =
        presentOperationalKnowledge(
          knowledge,
          consideration,
          productiveContext
        );

      if (!productiveInput) {
        throw new Error(
          'FASE 24.9 no pudo obtener ProductiveKnowledgeInput previo al alcance.'
        );
      }

      const reception =
        receiveProductiveKnowledge(productiveInput);

      const availability =
        makeProductiveKnowledgeAvailable(reception);

      const consumerA: ProductiveKnowledgeConsumerRef = {
        id: 'productive-consumer-a-24-9',
      };

      const consumerB: ProductiveKnowledgeConsumerRef = {
        id: 'productive-consumer-b-24-9',
      };

      const exposureA =
        exposeProductiveKnowledge(
          availability,
          consumerA
        );

      const exposureB =
        exposeProductiveKnowledge(
          availability,
          consumerB
        );

      const accessA =
        accessProductiveKnowledge(exposureA);

      const accessB =
        accessProductiveKnowledge(exposureB);

      const consumptionA =
        consumeProductiveKnowledge(accessA);

      const consumptionB =
        consumeProductiveKnowledge(accessB);

      const utilizationA =
        useProductiveKnowledge(consumptionA);

      const utilizationB =
        useProductiveKnowledge(consumptionB);

      const influenceA =
        influenceProductiveKnowledge(utilizationA);

      const influenceB =
        influenceProductiveKnowledge(utilizationB);

      /*
      * influence exists != influence reaches recommendation
      *
      * ProductiveKnowledgeInfluence no crea
      * automáticamente ningún
      * ProductiveKnowledgeRecommendationReach.
      *
      * El alcance requiere un acto explícito:
      * reachProductiveRecommendation().
      */
      const influenceASnapshot =
        JSON.stringify(influenceA);

      const influenceBSnapshot =
        JSON.stringify(influenceB);

      /*
      * Alcance explícito de Influence A
      * sobre la recomendación concreta.
      */
      const reachA =
        reachProductiveRecommendation(
          influenceA,
          recommendation
        );

      if (reachA.influence !== influenceA) {
        throw new Error(
          'FASE 24.9 no conservó la misma ProductiveKnowledgeInfluence durante el alcance.'
        );
      }

      if (reachA.recommendation !== recommendation) {
        throw new Error(
          'FASE 24.9 no conservó la misma IntelligenceRecommendation durante el alcance.'
        );
      }

      /*
      * La recomendación debe conservar identidad
      * y contenido exactos.
      */
      if (
        JSON.stringify(recommendation) !==
        recommendationSnapshot
      ) {
        throw new Error(
          'FASE 24.9 modificó la recomendación productiva durante el alcance.'
        );
      }

      /*
      * La influencia tampoco puede mutarse.
      */
      if (
        JSON.stringify(influenceA) !==
        influenceASnapshot
      ) {
        throw new Error(
          'FASE 24.9 modificó ProductiveKnowledgeInfluence durante el alcance.'
        );
      }

      /*
      * Influence B permanece independiente.
      */
      if (
        JSON.stringify(influenceB) !==
        influenceBSnapshot
      ) {
        throw new Error(
          'FASE 24.9 propagó o modificó indebidamente una influencia independiente.'
        );
      }

      /*
      * Control A/B:
      *
      * que Influence A alcance Recommendation R
      * no significa que Influence B la alcance
      * automáticamente.
      *
      * El segundo alcance requiere otro acto
      * explícito independiente.
      */
      const reachB =
        reachProductiveRecommendation(
          influenceB,
          recommendation
        );

      if (reachB.influence !== influenceB) {
        throw new Error(
          'FASE 24.9 no conservó la segunda influencia durante su alcance independiente.'
        );
      }

      if (reachB.recommendation !== recommendation) {
        throw new Error(
          'FASE 24.9 no conservó la misma recomendación durante el segundo alcance.'
        );
      }

      if (reachA === reachB) {
        throw new Error(
          'FASE 24.9 colapsó dos actos explícitos de alcance independientes.'
        );
      }

      if (reachA.influence === reachB.influence) {
        throw new Error(
          'FASE 24.9 perdió la distinción entre influencias productivas independientes.'
        );
      }

      if (reachA.recommendation !== reachB.recommendation) {
        throw new Error(
          'FASE 24.9 esperaba que ambas influencias alcanzaran exactamente la misma recomendación.'
        );
      }

      /*
      * ProductiveKnowledgeRecommendationReach debe
      * ser una relación mínima.
      *
      * No puede duplicar datos de Recommendation
      * ni adquirir semántica de efecto, cambio,
      * prioridad, ranking o selección.
      */
      const forbiddenReachProperties = [
        'recommendationId',
        'target',
        'targetId',
        'targetType',
        'purpose',
        'effect',
        'effectSize',
        'impact',
        'changed',
        'score',
        'priority',
        'strength',
        'weight',
        'support',
        'supportCount',
        'confidence',
        'rank',
        'ranking',
        'selected',
        'selection',
        'decision',
        'decisionId',
        'executed',
        'execution',
      ];

      const reachRecord =
        reachA as unknown as Record<
          string,
          unknown
        >;

      const detectedForbiddenReachProperty =
        forbiddenReachProperties.find(
          (property) => property in reachRecord
        );

      if (detectedForbiddenReachProperty) {
        throw new Error(
          `FASE 24.9 introdujo indebidamente la propiedad "${detectedForbiddenReachProperty}" dentro de ProductiveKnowledgeRecommendationReach.`
        );
      }

      /*
      * La recomendación original sí puede contener
      * score y priority porque pertenecen a su
      * contrato previo.
      *
      * 24.9 únicamente verifica que esos valores
      * no hayan sido alterados ni duplicados en Reach.
      */
      if (
        reachA.recommendation.score !==
          recommendation.score ||
        reachA.recommendation.priority !==
          recommendation.priority
      ) {
        throw new Error(
          'FASE 24.9 alteró score o priority de la recomendación alcanzada.'
        );
      }

      /*
      * La genealogía completa del conocimiento
      * debe seguir preservándose transitivamente.
      */
      if (
        reachA.influence.utilization.consumption.access.exposure
          .availability.reception.input !== productiveInput
      ) {
        throw new Error(
          'FASE 24.9 perdió ProductiveKnowledgeInput durante el alcance sobre recomendación.'
        );
      }

      if (
        reachA.influence.utilization.consumption.access.exposure
          .consumer !== consumerA
      ) {
        throw new Error(
          'FASE 24.9 perdió la referencia del consumidor durante el alcance sobre recomendación.'
        );
      }

      /*
      * Verificación productiva externa.
      *
      * La influencia alcanzó una recomendación
      * concreta, pero no produjo todavía efecto
      * ni modificación del resultado productivo.
      */
      const recommendationsAfterReach =
        generateRecommendationsFromPatterns(
          detectedPatterns
        );

      const decisionsAfterReach =
        generateOperationalDecisions(
          detectedPatterns,
          recommendationsAfterReach
        );

      if (
        JSON.stringify(
          recommendationsAfterReach
        ) !== recommendationsSnapshot
      ) {
        throw new Error(
          'FASE 24.9 detectó modificación de recomendaciones productivas después del alcance de la influencia.'
        );
      }

      if (
        JSON.stringify(decisionsAfterReach) !==
        decisionsSnapshot
      ) {
        throw new Error(
          'FASE 24.9 detectó modificación, reordenamiento o ranking distinto de decisiones después del alcance sobre recomendación.'
        );
      }

      addLog(
        `FASE 24.9 OK: las influencias del conocimiento ${productiveInput.knowledgeId} asociadas a ${consumerA.id} y ${consumerB.id} alcanzaron explícitamente la misma recomendación productiva ${recommendation.id} mediante actos independientes de ProductiveKnowledgeRecommendationReach, conservando exactamente influencia y recomendación.
        La influencia no produjo alcance automático; el alcance requirió reachProductiveRecommendation() y no modificó score, priority, contenido, ranking, selección ni ejecución de la recomendación.
        Permanecieron intactas ${recommendationsAfterReach.length} recomendaciones y ${decisionsAfterReach.length} decisiones productivas.`
      );
    } catch (error) {
      console.error(error);

      addLog(
        error instanceof Error
          ? `Error en alcance productivo explícito de la influencia sobre recomendación 24.9: ${error.message}`
          : 'Error inesperado en alcance productivo explícito de la influencia sobre recomendación 24.9.'
      );
    } finally {
      setLoading(false);
    }
  }

  async function testOperationalKnowledgeProductiveRecommendationEffectContract() {
    setLoading(true);

    try {
      const detectedPatterns = await detectMemoryPatterns();

      const recommendationsBeforeEffect =
        generateRecommendationsFromPatterns(detectedPatterns);

      const decisionsBeforeEffect =
        generateOperationalDecisions(
          detectedPatterns,
          recommendationsBeforeEffect
        );

      /*
      * FASE 24.10 — Efecto productivo observable
      * controlado sobre recomendación alcanzada
      * por conocimiento operativo.
      *
      * FASE 24.9 estableció:
      *
      * ProductiveKnowledgeInfluence
      *        +
      * IntelligenceRecommendation
      *        ↓
      * reachProductiveRecommendation()
      *        ↓
      * ProductiveKnowledgeRecommendationReach
      *
      * FASE 24.10 introduce:
      *
      * ProductiveKnowledgeRecommendationReach
      *        +
      * ProductiveKnowledgeRecommendationEffectContext
      *        ↓
      * observeProductiveKnowledgeRecommendationEffect()
      *        ↓
      * ProductiveKnowledgeRecommendationEffect | null
      *
      * La tesis es:
      *
      * influence exists
      *   != recommendation reach exists
      *   != observable effect exists
      *   != recommendation changes
      *
      * Un Reach válido no materializa automáticamente
      * un efecto observable.
      *
      * La existencia de un Effect tampoco constituye:
      *
      * - modificación de recomendación;
      * - cambio de contenido;
      * - cambio de score;
      * - cambio de priority;
      * - ranking;
      * - selección;
      * - ejecución;
      * - cambio de decisiones.
      */

      const recommendationsSnapshot =
        JSON.stringify(recommendationsBeforeEffect);

      const decisionsSnapshot =
        JSON.stringify(decisionsBeforeEffect);

      if (recommendationsBeforeEffect.length < 1) {
        throw new Error(
          'FASE 24.10 esperaba al menos 1 recomendación productiva existente.'
        );
      }

      const recommendation =
        recommendationsBeforeEffect[0];

      if (!recommendation) {
        throw new Error(
          'FASE 24.10 no pudo resolver una recomendación productiva concreta.'
        );
      }

      const recommendationSnapshot =
        JSON.stringify(recommendation);

      /*
      * Conocimiento controlado exclusivo de 24.10.
      */
      const controlledPatterns: MemoryPattern[] = [
        {
          id: 'pattern-controlled-productive-recommendation-effect-24-10',
          title:
            'Patrón controlado de efecto productivo observable sobre recomendación',
          description:
            'Patrón controlado utilizado exclusivamente por FASE 24.10.',
          score: 100,
          occurrences: 4,
          kind: 'recommendation-deviation-recurrence',
          context: {
            movementType: 'reubicacion',
            deviationReason:
              'motivo-controlado-productive-recommendation-effect-24-10',
          },
          evidence: {
            memoryIds: [
              'memory-controlled-productive-recommendation-effect-24-10-1',
              'memory-controlled-productive-recommendation-effect-24-10-2',
              'memory-controlled-productive-recommendation-effect-24-10-3',
              'memory-controlled-productive-recommendation-effect-24-10-4',
            ],
          },
        },
      ];

      const controlledKnowledge =
        generateOperationalKnowledge(controlledPatterns);

      if (controlledKnowledge.length !== 1) {
        throw new Error(
          `FASE 24.10 esperaba exactamente 1 conocimiento controlado y generó ${controlledKnowledge.length}.`
        );
      }

      const knowledge = controlledKnowledge[0];

      if (!knowledge) {
        throw new Error(
          'FASE 24.10 no pudo resolver el conocimiento controlado.'
        );
      }

      const productiveContext = {
        movementType: 'reubicacion' as const,
      };

      const eligibility =
        evaluateOperationalKnowledgeEligibility(
          knowledge,
          productiveContext
        );

      if (
        eligibility.eligible !== true ||
        eligibility.reason !== 'context-compatible'
      ) {
        throw new Error(
          'FASE 24.10 no pudo establecer elegibilidad contextual previa.'
        );
      }

      const consideration =
        considerOperationalKnowledge(eligibility);

      if (!consideration) {
        throw new Error(
          'FASE 24.10 no pudo establecer consideración previa del conocimiento.'
        );
      }

      const productiveInput =
        presentOperationalKnowledge(
          knowledge,
          consideration,
          productiveContext
        );

      if (!productiveInput) {
        throw new Error(
          'FASE 24.10 no pudo obtener ProductiveKnowledgeInput previo al efecto observable.'
        );
      }

      const reception =
        receiveProductiveKnowledge(productiveInput);

      const availability =
        makeProductiveKnowledgeAvailable(reception);

      const consumer: ProductiveKnowledgeConsumerRef = {
        id: 'productive-consumer-effect-24-10',
      };

      const exposure =
        exposeProductiveKnowledge(
          availability,
          consumer
        );

      const access =
        accessProductiveKnowledge(exposure);

      const consumption =
        consumeProductiveKnowledge(access);

      const utilization =
        useProductiveKnowledge(consumption);

      const influence =
        influenceProductiveKnowledge(utilization);

      const reach =
        reachProductiveRecommendation(
          influence,
          recommendation
        );

      /*
      * Snapshots inmediatamente anteriores
      * a la nueva frontera de 24.10.
      */
      const influenceSnapshot =
        JSON.stringify(influence);

      const reachSnapshot =
        JSON.stringify(reach);

      /*
      * CONTROL NEGATIVO
      *
      * El Reach es válido, pero la recomendación
      * alcanzada está fuera del ámbito explícito
      * de observación.
      *
      * Reach existe != Effect existe.
      */
      const effectOutsideObservationScope =
        observeProductiveKnowledgeRecommendationEffect(
          reach,
          {
            observableRecommendationId:
              `${recommendation.id}-outside-observation-scope-24-10`,
          }
        );

      if (effectOutsideObservationScope !== null) {
        throw new Error(
          'FASE 24.10 materializó indebidamente un efecto observable fuera del ámbito explícito de observación.'
        );
      }

      /*
      * El control negativo no puede modificar
      * Reach, Influence ni Recommendation.
      */
      if (
        JSON.stringify(reach) !==
        reachSnapshot
      ) {
        throw new Error(
          'FASE 24.10 modificó ProductiveKnowledgeRecommendationReach durante el control negativo.'
        );
      }

      if (
        JSON.stringify(influence) !==
        influenceSnapshot
      ) {
        throw new Error(
          'FASE 24.10 modificó ProductiveKnowledgeInfluence durante el control negativo.'
        );
      }

      if (
        JSON.stringify(recommendation) !==
        recommendationSnapshot
      ) {
        throw new Error(
          'FASE 24.10 modificó la recomendación durante el control negativo.'
        );
      }

      /*
      * CASO POSITIVO
      *
      * Se utiliza exactamente el mismo Reach.
      *
      * Sólo cambia el contexto explícito
      * de observación.
      */
      const observableEffect =
        observeProductiveKnowledgeRecommendationEffect(
          reach,
          {
            observableRecommendationId:
              recommendation.id,
          }
        );

      if (!observableEffect) {
        throw new Error(
          'FASE 24.10 no materializó el efecto observable esperado dentro del ámbito explícito de observación.'
        );
      }

      /*
      * Effect debe conservar exactamente
      * el mismo Reach.
      */
      if (observableEffect.reach !== reach) {
        throw new Error(
          'FASE 24.10 no conservó exactamente el mismo ProductiveKnowledgeRecommendationReach dentro del efecto observable.'
        );
      }

      /*
      * Y, transitivamente, la misma Influence.
      */
      if (
        observableEffect.reach.influence !==
        influence
      ) {
        throw new Error(
          'FASE 24.10 no conservó exactamente la misma ProductiveKnowledgeInfluence dentro del efecto observable.'
        );
      }

      /*
      * Y exactamente la misma Recommendation.
      */
      if (
        observableEffect.reach.recommendation !==
        recommendation
      ) {
        throw new Error(
          'FASE 24.10 no conservó exactamente la misma IntelligenceRecommendation dentro del efecto observable.'
        );
      }

      if (
        observableEffect.effectType !==
        'knowledge-influence-observed'
      ) {
        throw new Error(
          'FASE 24.10 produjo un tipo de efecto observable distinto del contrato esperado.'
        );
      }

      /*
      * ProductiveKnowledgeRecommendationEffect debe
      * permanecer como resultado mínimo observacional.
      *
      * No puede adquirir semántica de valoración,
      * transformación, ranking, selección o ejecución.
      */
      const forbiddenEffectProperties = [
        'recommendationId',
        'influenceId',
        'target',
        'targetId',
        'targetType',
        'purpose',
        'effectSize',
        'impact',
        'changed',
        'transformed',
        'score',
        'priority',
        'strength',
        'weight',
        'support',
        'supportCount',
        'confidence',
        'rank',
        'ranking',
        'selected',
        'selection',
        'decision',
        'decisionId',
        'executed',
        'execution',
        'accepted',
        'rejected',
        'preferred',
        'promoted',
      ];

      const effectRecord =
        observableEffect as unknown as Record<
          string,
          unknown
        >;

      const detectedForbiddenEffectProperty =
        forbiddenEffectProperties.find(
          (property) => property in effectRecord
        );

      if (detectedForbiddenEffectProperty) {
        throw new Error(
          `FASE 24.10 introdujo indebidamente la propiedad "${detectedForbiddenEffectProperty}" dentro de ProductiveKnowledgeRecommendationEffect.`
        );
      }

      /*
      * El nuevo efecto no puede modificar
      * ninguno de sus antecedentes causales.
      */
      if (
        JSON.stringify(reach) !==
        reachSnapshot
      ) {
        throw new Error(
          'FASE 24.10 modificó ProductiveKnowledgeRecommendationReach al materializar el efecto observable.'
        );
      }

      if (
        JSON.stringify(influence) !==
        influenceSnapshot
      ) {
        throw new Error(
          'FASE 24.10 modificó ProductiveKnowledgeInfluence al materializar el efecto observable.'
        );
      }

      if (
        JSON.stringify(recommendation) !==
        recommendationSnapshot
      ) {
        throw new Error(
          'FASE 24.10 modificó la recomendación productiva al materializar el efecto observable.'
        );
      }

      /*
      * Score y priority pertenecen al contrato
      * preexistente de IntelligenceRecommendation.
      *
      * El Effect puede alcanzarlos sólo
      * transitivamente mediante Reach, pero
      * no duplicarlos ni modificarlos.
      */
      if (
        observableEffect.reach.recommendation.score !==
          recommendation.score ||
        observableEffect.reach.recommendation.priority !==
          recommendation.priority
      ) {
        throw new Error(
          'FASE 24.10 alteró score o priority de la recomendación asociada al efecto observable.'
        );
      }

      /*
      * Preservación genealógica completa.
      *
      * Effect
      *   ↓
      * Reach
      *   ↓
      * Influence
      *   ↓
      * Utilization
      *   ↓
      * Consumption
      *   ↓
      * Access
      *   ↓
      * Exposure
      *   ↓
      * Availability
      *   ↓
      * Reception
      *   ↓
      * ProductiveKnowledgeInput
      */
      if (
        observableEffect.reach.influence.utilization
          .consumption.access.exposure.availability
          .reception.input !== productiveInput
      ) {
        throw new Error(
          'FASE 24.10 perdió ProductiveKnowledgeInput dentro de la genealogía del efecto observable.'
        );
      }

      if (
        observableEffect.reach.influence.utilization
          .consumption.access.exposure.consumer !==
        consumer
      ) {
        throw new Error(
          'FASE 24.10 perdió la referencia del consumidor dentro de la genealogía del efecto observable.'
        );
      }

      /*
      * Verificación productiva externa.
      *
      * Un efecto observable existe, pero la
      * recomendación productiva permanece intacta.
      */
      const recommendationsAfterEffect =
        generateRecommendationsFromPatterns(
          detectedPatterns
        );

      const decisionsAfterEffect =
        generateOperationalDecisions(
          detectedPatterns,
          recommendationsAfterEffect
        );

      if (
        JSON.stringify(recommendationsAfterEffect) !==
        recommendationsSnapshot
      ) {
        throw new Error(
          'FASE 24.10 detectó modificación de recomendaciones productivas después de materializar el efecto observable.'
        );
      }

      if (
        JSON.stringify(decisionsAfterEffect) !==
        decisionsSnapshot
      ) {
        throw new Error(
          'FASE 24.10 detectó modificación, reordenamiento o ranking distinto de decisiones después de materializar el efecto observable.'
        );
      }

      addLog(
        `FASE 24.10 OK: el mismo ProductiveKnowledgeRecommendationReach sobre la recomendación ${recommendation.id} no materializó efecto fuera del ámbito explícito de observación y sí materializó ProductiveKnowledgeRecommendationEffect dentro de dicho ámbito, conservando exactamente Reach, Influence y Recommendation.
        El efecto observable ${observableEffect.effectType} no modificó contenido, score, priority, ranking, selección ni ejecución de la recomendación.
        Permanecieron intactas ${recommendationsAfterEffect.length} recomendaciones y ${decisionsAfterEffect.length} decisiones productivas.`
      );
    } catch (error) {
      console.error(error);

      addLog(
        error instanceof Error
          ? `Error en efecto productivo observable sobre recomendación 24.10: ${error.message}`
          : 'Error inesperado en efecto productivo observable sobre recomendación 24.10.'
      );
    } finally {
      setLoading(false);
    }
  }

